const handleSendMessage = async () => {
  if (userInput.trim() === "") return;

  // 사용자의 메시지 추가
  setChatHistory((prevHistory) => [
    ...prevHistory,
    { sender: "user", message: userInput },
  ]);

  // 입력창 비우기 (메시지 전송 직후)
  setUserInput("");

  try {
    const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ user_input: userInput, personality }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      // 서버에서 반환한 오류 메시지 상세 출력
      console.error("Server Error:", errorData.detail);
      throw new Error(errorData.detail || "챗봇 응답을 처리하는 중 오류가 발생했습니다.");
    }

    const data = await response.json();
    const chatbotMessage = typeof data.response === "string"
      ? data.response
      : JSON.stringify(data.response);

    // 챗봇 응답을 chatHistory에 추가
    setChatHistory((prevHistory) => [
      ...prevHistory,
      { sender: "chatbot", message: chatbotMessage },
    ]);
  } catch (error) {
    console.error("Error fetching chatbot response:", error);
    if (error.message === "욕설은 사용할 수 없습니다.") {
      setError("입력하신 메시지에 부적절한 단어가 포함되어 있습니다.");  // 경고 메시지
    } else {
      setError("서버에서 오류가 발생했습니다. 다시 시도해 주세요.");  // 서버 오류 메시지
    }
  }
};
